//! 🌳️ Optional original document records expose one borrowed reference key per admitted turn.
use super::*;
/// 🧭️ A declared original root source retains its document while its fixed path and indexed keys are read.
pub trait RootReferenceSource:Send+Sync+'static{fn len(original:&EnergyModelSnapshot)->usize;fn key(original:&EnergyModelSnapshot,index:usize)->Result<u32,ValueError>;}
/// 🧳️ The exact deleted-row and document bindings survive every yielded key and cancelled prefix.
pub struct RootReferenceGuard<S:RootReferenceSource>{original:Option<RetainedCloneBinding>,deleted:Option<RetainedCloneBinding>,index:usize,allowed:Option<bool>,phase:u8,closing:bool,marker:std::marker::PhantomData<S>}
impl<S:RootReferenceSource,R:EntityRow> RowDeletionGuard<R> for RootReferenceGuard<S>{
 fn new()->Self{Self{original:None,deleted:None,index:0,allowed:None,phase:0,closing:false,marker:Default::default()}}
 fn demand(&self,row:RetainedCloneRef<'_,R>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,_:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==99{return Err(invalid());}row.check_binding(&self.deleted)?;original.check_binding(&self.original)?;match self.phase{0=>nested(scalar(row.binding_copy_bytes()),1),1=>nested(scalar(original.binding_copy_bytes()),1),2=>Ok(scalar(4*size_of::<usize>()+2*size_of::<u32>()+2*size_of::<Option<bool>>()+1)),_=>Err(invalid())}}
 fn advance(&mut self,row:RetainedCloneRef<'_,R>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=<Self as RowDeletionGuard<R>>::demand(self,row,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{0=>{p=add(row.bind(&mut self.deleted,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=1;},1=>{p=add(original.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{if self.index>=S::len(original.get()){self.allowed=Some(true);self.phase=99;}else{let found=S::key(original.get(),self.index)?==row.get().entity_id();self.index+=1;if found{self.allowed=Some(false);self.phase=99;}}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy root reference restriction")?;Ok(if self.phase==99{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<bool>{if !self.closing&&self.phase==99{self.allowed}else{None}}
 fn begin_close(&mut self){self.closing=true;}
}
impl<S:RootReferenceSource> CursorClose for RootReferenceGuard<S>{fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}RetainedCloneBinding::close_demand(if self.deleted.is_some(){&self.deleted}else{&self.original},b)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let s=RetainedCloneBinding::close_one(if self.deleted.is_some(){&mut self.deleted}else{&mut self.original},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}fn terminal_is_empty(&self)->bool{self.closing&&self.deleted.is_none()&&self.original.is_none()}}
impl<S:RootReferenceSource> Drop for RootReferenceGuard<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original root reference restriction retains source bindings");}}
